INSERT INTO `question` VALUES (1,1,'Node.js sử dụng JavaScript engine nào?','MULTIPLE_CHOICE','[\"SpiderMonkey\", \"V8\", \"Chakra\", \"JavaScriptCore\"]','[\"V8\"]',1.00,0,'Node.js dùng V8 engine của Google Chrome','2026-07-20 13:18:59','2026-07-20 13:52:46'),(2,1,'npm là viết tắt của gì?','MULTIPLE_CHOICE','[\"Node Package Manager\", \"Node Program Manager\", \"New Package Maker\", \"Node Project Manager\"]','[\"Node Package Manager\"]',1.00,1,'npm = Node Package Manager','2026-07-20 13:18:59','2026-07-20 13:52:46'),(3,1,'Middleware trong Express.js dùng để làm gì?','MULTIPLE_CHOICE','[\"Kết nối database\", \"Xử lý request/response pipeline\", \"Tạo HTML templates\", \"Quản lý sessions\"]','[\"Xử lý request/response pipeline\"]',1.00,2,'Middleware xử lý request','2026-07-20 13:18:59','2026-07-20 13:52:46'),(4,1,'Phương thức HTTP nào dùng để cập nhật một phần resource?','MULTIPLE_CHOICE','[\"PUT\", \"PATCH\", \"POST\", \"UPDATE\"]','[\"PATCH\"]',1.00,3,'PATCH dùng để update một phần','2026-07-20 13:18:59','2026-07-20 13:52:46'),(5,1,'MongoDB thuộc loại database nào?','MULTIPLE_CHOICE','[\"Relational\", \"Graph\", \"Document/NoSQL\", \"Key-Value\"]','[\"Document/NoSQL\"]',1.00,4,'MongoDB là NoSQL document database','2026-07-20 13:18:59','2026-07-20 13:52:46'),(6,2,'Trong Java, từ khóa nào dùng để kế thừa class?','MULTIPLE_CHOICE','[\"extends\", \"implements\", \"inherits\", \"super\"]','[\"extends\"]',1.00,0,'Từ khóa extends dùng để kế thừa class','2026-07-20 13:18:59','2026-07-20 13:52:46'),(7,2,'Phương thức main() trong Java có kiểu trả về là gì?','MULTIPLE_CHOICE','[\"int\", \"String\", \"void\", \"null\"]','[\"void\"]',1.00,1,'Phương thức main trả về void','2026-07-20 13:18:59','2026-07-20 13:52:46'),(8,2,'@Autowired trong Spring dùng để làm gì?','MULTIPLE_CHOICE','[\"Tạo bean mới\", \"Inject dependency tự động\", \"Cấu hình database\", \"Xử lý request\"]','[\"Inject dependency tự động\"]',1.00,2,'@Autowired tự động inject dependency','2026-07-20 13:18:59','2026-07-20 13:52:46'),(9,2,'Collection nào không cho phép phần tử trùng lặp?','MULTIPLE_CHOICE','[\"ArrayList\", \"LinkedList\", \"HashSet\", \"Vector\"]','[\"HashSet\"]',1.00,3,'HashSet implements Set interface','2026-07-20 13:18:59','2026-07-20 13:52:46'),(10,2,'@Transactional dùng để làm gì?','MULTIPLE_CHOICE','[\"Tạo transaction email\", \"Quản lý database transaction\", \"Xử lý HTTP request\", \"Tạo REST API\"]','[\"Quản lý database transaction\"]',1.00,4,'@Transactional quản lý database transaction','2026-07-20 13:18:59','2026-07-20 13:52:46'),(11,3,'Lệnh nào dùng để khởi tạo một Git repository mới?','MULTIPLE_CHOICE','[\"git start\", \"git init\", \"git create\", \"git new\"]','[\"git init\"]',1.00,0,'git init khởi tạo một repository Git mới','2026-07-29 11:22:47','2026-07-29 11:22:47'),(12,3,'Lệnh nào dùng để thêm tất cả file vào staging area?','MULTIPLE_CHOICE','[\"git push\", \"git commit\", \"git add .\", \"git save\"]','[\"git add .\"]',1.00,1,'git add . thêm tất cả file vào staging area','2026-07-29 11:22:47','2026-07-29 11:22:47'),(13,3,'Lệnh nào dùng để lưu thay đổi vào repository?','MULTIPLE_CHOICE','[\"git save\", \"git commit -m message\", \"git store\", \"git push\"]','[\"git commit -m message\"]',1.00,2,'git commit lưu thay đổi vào repository','2026-07-29 11:22:47','2026-07-29 11:22:47'),(14,3,'Lệnh nào dùng để tạo một branch mới?','MULTIPLE_CHOICE','[\"git new\", \"git branch name\", \"git create\", \"git switch -c\"]','[\"git branch name\"]',1.00,3,'git branch tạo một branch mới','2026-07-29 11:22:47','2026-07-29 11:22:47'),(15,3,'Lệnh nào dùng để chuyển đổi giữa các branch?','MULTIPLE_CHOICE','[\"git switch\", \"git checkout\", \"git change\", \"Cả A và B\"]','[\"Cả A và B\"]',1.00,4,'git switch và git checkout đều dùng để chuyển branch','2026-07-29 11:22:47','2026-07-29 11:22:47'),(16,3,'Làm sao để xem lịch sử commit?','MULTIPLE_CHOICE','[\"git history\", \"git log\", \"git commits\", \"git show\"]','[\"git log\"]',1.00,5,'git log hiển thị lịch sử commit','2026-07-29 11:22:47','2026-07-29 11:22:47'),(17,3,'Lệnh nào dùng để hợp nhất branch?','MULTIPLE_CHOICE','[\"git combine\", \"git merge branch\", \"git join\", \"git unite\"]','[\"git merge branch\"]',1.00,6,'git merge hợp nhất branch vào branch hiện tại','2026-07-29 11:22:47','2026-07-29 11:22:47'),(18,3,'Lệnh nào dùng để gửi code lên remote?','MULTIPLE_CHOICE','[\"git upload\", \"git send\", \"git push\", \"git deploy\"]','[\"git push\"]',1.00,7,'git push gửi commit local lên remote','2026-07-29 11:22:47','2026-07-29 11:22:47'),(19,3,'Lệnh nào dùng để lấy code mới từ remote?','MULTIPLE_CHOICE','[\"git download\", \"git pull\", \"git get\", \"git fetch\"]','[\"git pull\"]',1.00,8,'git pull lấy code từ remote về local','2026-07-29 11:22:47','2026-07-29 11:22:47'),(20,3,'Trạng thái của file sau khi git add là gì?','MULTIPLE_CHOICE','[\"Committed\", \"Staged\", \"Modified\", \"Untracked\"]','[\"Staged\"]',1.00,9,'Sau git add, file ở trạng thái Staged','2026-07-29 11:22:47','2026-07-29 11:22:47');
